declare global {
  /**
   * Объект со строковыми ключами и значениями неизвестного типа.
   * Нужен для типобезопасной работы с динамическими словарями.
   */
  type UnknownObject = Record<string, unknown>;

  /**
   * Пустой объект.
   * Нужен там, где ожидается отсутствие свойств.
   */
  type EmptyObject = {};

  /**
   * Обобщённый тип функции с типизированными параметрами и результатом.
   * Нужен для описания функций с гибкой сигнатурой.
   */
  type Func<Args extends unknown[], R> = (...a: Args) => R;

  /**
   * Обобщённый тип для произвольной функции с неизвестными аргументами и возвращаемым значением.
   * Нужен для описания унифицированных сигнатур без потери типизации.
   */
  type AnyFunction = Func<any[], any>;

  /**
   * Раскрывает (упрощает) тип до явных свойств.
   * Нужен для повышения читаемости сложных типов.
   */
  type Expand<T> = T extends unknown
    ? T extends infer O
      ? { [K in keyof O]: O[K] }
      : never
    : never;
}

export {};
